        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(inp):
    h=len(inp); w=len(inp[0])
    bg=collections.Counter(sum(inp,[])).most_common(1)[0][0]
    # full-height/separators: rows or cols of a single non-bg repeated value
    zr=[i for i in range(h) if len(set(inp[i]))==1 and inp[i][0]!=bg]
    zc=[j for j in range(w) if len({inp[i][j] for i in range(h)})==1 and inp[0][j]!=bg]
    def split(n,idxs):
        o=[];s=0
        for x in sorted(idxs)+[n]:
            if x>s: o.append((s,x-1)); s=x+1
        return o
    rr=split(h,zr); cc=split(w,zc)
    noise=[v for v in collections.Counter(sum(inp,[])).keys() if v not in (bg,) and False]
    noise=set(v for row in inp for v in row)-{bg}|set([inp[i][j] for i,j in [(a,b)] for a in zr for b in zc])-set(zr)*[None]-set(zc)*[None]
    noise=set(v for row in inp for v in row)
    noise={v for v in noise}-{bg}
    # separator values excluded from noise counts (they're the row/col colors)
    sepvals={inp[i][0] for i in zr}|{inp[0][j] for j in zc}
    nc=list(noise-sepvals)[0] if len(noise-sepvals)>0 else None
    total=sum(row.count(nc) for row in inp)
    qtotal=sum(sum(row[c:c2+1].count(nc) for row in inp[a:b+1]) for a,b in rr for c,c2 in cc)
    mc=(qtotal/len(rr*cc)) if rr and cc else 0
    pred=[row[:] for row in inp]
    for a in rr:
        for b in cc:
            cnt=sum(row[b[0]:b[1]+1].count(nc) for row in inp[a[0]:a[1]+1])
            if cnt > mc:
                for r in range(a[0],a[1]+1):
                    for c in range(b[0],b[1]+1): pred[r][c]=nc
    return pred
