    bg=collections.Counter(sum(inp,[])).most_common(1)[0][0]
    zr=[i for i in range(h) if len(set(inp[i]))==1 and inp[i][0]!=bg]
    zc=[j for j in range(w) if len({inp[i][j] for i in range(h)})==1 and inp[0][j]!=bg]
    def split(n,idxs):
        o=[];s=0
        for x in sorted(idxs)+[n]:
            if x>s: o.append((s,x-1)); s=x+1
        return o
    rr=split(h,zr); cc=split(w,zc)
    sep={inp[i][0] for i in zr}|{inp[0][j] for j in zc}
    noise=set(v for row in inp for v in row)-sep-{bg}
    nc=noise.pop() if noise else None
    Q=[[sum(row[c:c2+1].count(nc) for row in inp[a:b+1]) for c,c2 in cc] for a,b in rr]
    M=max(max(r) for r in Q)
    pred=[row[:] for row in inp]
    for i,(a,b) in enumerate(rr):
        for j,(c,d2) in enumerate(cc):
            cnt=Q[i][j]
            if cnt>=M:
                for r_ in range(a,b+1):
                    for c_ in range(c,d2+1): pred[r_][c_]=nc
            else:
                for r_ in range(a,b+1):
                    for c_ in range(c,d2+1):
                        if inp[r_][c_]==nc: pred[r_][c_]=bg
    return pred,Q,M
