def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(inp):
    h=len(inp); w=len(inp[0])
    cnt=collections.Counter(v for row in inp for v in row)
    bg=max(cnt,key=lambda v:cnt[v])
    fullrows={inp[i][0] for i in range(h) if len(set(inp[i]))==1}
    fullcols={inp[0][j] for j in range(w) if len({inp[i][j] for i in range(h)})==1}
    sc=set(fullrows)&set(fullcols)
    s=min(sc,default=None)
    zr=[i for i in range(h) if all(inp[i][j]==s for j in range(w))]
    zc=[j for j in range(w) if all(inp[i][j]==s for i in range(h))]
    def split(n,idxs):
        o=[]; s_=0
        for x in sorted(idxs)+[n]:
            if x>s_: o.append((s_,x-1)); s_=x+1
        return o
    rr=split(h,zr); cc=split(w,zc)
    noise=[v for v in cnt if v!=s and v!=bg]
    nc=noise.pop() if noise else None
    Q=[[sum(row[c:c2+1].count(nc) for row in inp[a:b+1]) for c,c2 in cc] for a,b in rr]
    M=max(max(r) for r in Q)
    pred=[row[:] for row in inp]
    for i,(a,b) in enumerate(rr):
        for j,(c,d2) in enumerate(cc):
            if Q[i][j]>=M:
                for r_ in range(a,b+1):
                    for c_ in range(c,d2+1): pred[r_][c_]=nc
            else:
                for r_ in range(a,b+1):
                    for c_ in range(c,d2+1):
                        if inp[r_][c_]==nc: pred[r_][c_]=bg
    return pred,Q,M
for p in (1,2,3):
    P,solve_q,_=solve(G[f'Demo pair {p} input'])
    print('pair',p,'match:',P==G[f'Demo pair {p} output'],'counts',solve_q)
